{
  "vulnerable_symbols": [
    "yaml.full_load",
    "yaml.load"
  ],
  "trigger": "应用使用 PyYAML <5.4 的 yaml.full_load 或 yaml.load(Loader=FullLoader) 解析攻击者可控 YAML，且 YAML 含 !!python/object/new 标签。",
  "preconditions": [
    "PyYAML 版本低于 5.4",
    "yaml.load 使用 FullLoader（或默认 FullLoader）",
    "待解析 YAML 中包含 !!python/object/new 等 Python 对象构造标签"
  ],
  "exploit_evidence": [
    {
      "src": 0,
      "kind": "poc",
      "quote": "RCE in PyYAML before 5.4 via !!python/object/new tags with FullLoader."
    },
    {
      "src": 1,
      "kind": "poc",
      "quote": "EIP currently links 5 repository PoCs, 6 curated repository PoCs, and 2 lab environments to CVE-2020-14343."
    },
    {
      "src": 2,
      "kind": "poc",
      "quote": "PyYAML 在使用 yaml.load() 解析不可信数据时,未限制危险的 YAML 标签(如 !!python/object),攻击者可构造恶意 YAML 内容执行任意 Python 代码。"
    },
    {
      "src": 4,
      "kind": "poc",
      "quote": "When PyYAML uses yaml.load() to parse untrusted data, it does not restrict dangerous YAML tags (such as !!python/object), allowing attackers to craft malicious YAML content to execute arbitrary Python code."
    }
  ],
  "fixed_version": "5.4",
  "summary_zh": "PyYAML5.3用FullLoader解析不可信YAML可RCE，请升级5.4或safe_load。"
}
